// LiuOS: the laptop desktop (lock screen, sign-in, desktop, windows, dock, apps).
//
// LiuOS doesn't know the room exists. It talks only through announcements:
//   Listens for:  laptop:open {opener}       open the laptop (the room checks the camera first)
//                 laptop:close               close it
//                 laptop:open-app {name}     open straight into an app (nothing sends this right now)
//                 laptop:screen-request      repaint and send the screen picture
//   Announces:    laptop:opened / laptop:closed
//                 laptop:apps-changed {active}            which app window is in front (no listener right now)
//                 laptop:screen {canvas,redrawn,powered}  the picture for the 3D laptop screen

import { LIUOS_CONFIG } from './settings.js';
// Same URL as the room's import, so the browser loads Three.js once and shares it.
const THREE = await import('https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js');
const motionPreference = matchMedia('(prefers-reduced-motion: reduce)');
const reducedMotion = () => motionPreference.matches;

const markup = await fetch(new URL('laptop.html', import.meta.url)).then(response => response.text());
// The résumé shown in the Resume app: the shared web copy (the in-room viewer shows the same file).
const resumeSheet = await fetch(new URL('../assets/resume/resume.html', import.meta.url)).then(response => response.text());
document.body.insertAdjacentHTML('beforeend', markup);

const osElement=document.getElementById('laptop-window');osElement.style.setProperty('--os-window-animation',LIUOS_CONFIG.windows.animationMs+'ms');osElement.style.setProperty('--os-dock-height',(LIUOS_CONFIG.dock.height||52)+'px');
for(const [name,value] of Object.entries(LIUOS_CONFIG.colors))osElement.style.setProperty('--os-'+name,value);
for(const [name,value] of Object.entries(LIUOS_CONFIG.typography))document.documentElement.style.setProperty('--os-'+name,name==='bodyLineHeight'?String(value):value+'px');
document.documentElement.style.setProperty('--focus-accent',LIUOS_CONFIG.colors.accent);
for(const [name,value] of Object.entries({font:LIUOS_CONFIG.font,labelFont:LIUOS_CONFIG.labelFont,blur:LIUOS_CONFIG.blur+'px',radius:LIUOS_CONFIG.radius+'px',transition:LIUOS_CONFIG.transitionMs+'ms'}))osElement.style.setProperty('--os-'+name,value);

const laptopDialog=document.getElementById('laptop-window');let laptopReturnFocus=null,laptopPowered=true,laptopUnlocked=false;
const ios=/iP(hone|od|ad)/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const safari=ios&&!/CriOS|FxiOS|EdgiOS|OPiOS|OPT\/|DuckDuckGo|Chrome|Chromium/i.test(navigator.userAgent);
// The in-room screen keeps a static wallpaper frame and minute-based clock updates.
// The live shader is reserved for the visible LiuOS screen to keep room rendering light.
// Safari/iPhone: a 2048 screen texture plus a second WebGL wallpaper is what ran the tab out of memory.
const screenCanvas=document.createElement('canvas');screenCanvas.width=safari?1024:LIUOS_CONFIG.screen.resolution;screenCanvas.height=Math.round(screenCanvas.width/LIUOS_CONFIG.screen.aspect);
const screenContext=screenCanvas.getContext('2d');
let screenMinute='',screenState='',screenClockTimer=0;
function localClock(now=new Date()){return {time:now.toLocaleTimeString([],{hour:'numeric',minute:'2-digit',hour12:false}),date:now.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'})};}
function drawScreen(force=false){const now=new Date(),minute=Math.floor(now.getTime()/60000),state=laptopPowered+'/'+laptopUnlocked;if(!force&&minute===screenMinute&&state===screenState)return false;screenMinute=minute;screenState=state;
 const ctx=screenContext,w=screenCanvas.width,h=screenCanvas.height,c=LIUOS_CONFIG.colors;ctx.clearRect(0,0,w,h);ctx.fillStyle=laptopPowered?c.base:c.bezel;ctx.fillRect(0,0,w,h);
 if(laptopPowered){
 ctx.save();ctx.translate(w*.48,h*.43);ctx.scale(w*.52*Math.SQRT2,h*.57*Math.SQRT2);const paper=ctx.createRadialGradient(0,0,0,0,0,1);paper.addColorStop(0,c.base);paper.addColorStop(.2,c.base);paper.addColorStop(1,c.paperEdge);ctx.fillStyle=paper;ctx.fillRect(-2,-2,4,4);ctx.restore();
 const cell=w/40;ctx.save();ctx.strokeStyle=c.border;ctx.globalAlpha=.22;ctx.lineWidth=Math.max(1,w/950);ctx.beginPath();for(let x=cell/2;x<w;x+=cell){ctx.moveTo(x,0);ctx.lineTo(x,h);}for(let y=cell/2;y<h;y+=cell){ctx.moveTo(0,y);ctx.lineTo(w,y);}ctx.stroke();ctx.restore();
 const label=(text,size,y)=>{ctx.font=`500 ${Math.round(w*size)}px ${LIUOS_CONFIG.labelFont}`;ctx.letterSpacing=Math.round(w*size*.12)+'px';ctx.fillText(text.toUpperCase(),w*.5,y);ctx.letterSpacing='0px';};
 ctx.textAlign='center';ctx.fillStyle=c.text;const clock=localClock(now);ctx.font=`400 ${Math.round(w*.135)}px ${LIUOS_CONFIG.font}`;ctx.fillText(clock.time,w*.5,h*.43);
 ctx.fillStyle=c.muted;label(clock.date,.02,h*.53);label('LiuOS',.016,h*.64);label(laptopUnlocked?'Workspace ready · Click to open':'Click to open',.014,h*.9);
 }
 const glare=ctx.createLinearGradient(0,h,w,0),opacity=LIUOS_CONFIG.screen.glareOpacity;glare.addColorStop(0,'rgba(255,255,255,0)');glare.addColorStop(.35,'rgba(255,255,255,0)');glare.addColorStop(.48,`rgba(255,255,255,${opacity})`);glare.addColorStop(.65,'rgba(255,255,255,0)');glare.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=glare;ctx.fillRect(0,0,w,h);
 const vignette=ctx.createRadialGradient(w/2,h/2,h*.2,w/2,h/2,w*.6);vignette.addColorStop(0,c.bezel+'00');vignette.addColorStop(1,c.bezel+Math.round(LIUOS_CONFIG.screen.vignetteOpacity*255).toString(16).padStart(2,'0'));ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);
 return true;
}
function announceScreen(redrawn){document.dispatchEvent(new CustomEvent('laptop:screen',{detail:{canvas:screenCanvas,redrawn,powered:laptopPowered}}));}
function announceApps(){let active=null;if(laptopDialog.open&&laptopUnlocked){const focused=document.querySelector('.os-window.os-focused:not(.os-closing):not([hidden])');active=focused?.dataset.appWindow;}document.dispatchEvent(new CustomEvent('laptop:apps-changed',{detail:{active}}));}
document.addEventListener('laptop:screen-request',()=>{announceScreen(drawScreen());scheduleScreenClock();});
function scheduleScreenClock(){clearTimeout(screenClockTimer);if(document.hidden)return;screenClockTimer=setTimeout(()=>{if(drawScreen())announceScreen(true);scheduleScreenClock();},60000-Date.now()%60000+25);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(screenClockTimer);else{if(drawScreen())announceScreen(true);scheduleScreenClock();}});
function syncLaptop(){document.getElementById('lock-screen').hidden=laptopUnlocked;document.getElementById('desktop').hidden=!laptopUnlocked;document.getElementById('power-off').hidden=!laptopPowered;announceScreen(drawScreen());announceApps();updateWallpaperState();}
let puzzleCloseTimer=0,osClockTimer=0,osUnlockTimer=0,signinRevealed=false,osUnlocking=false,alternateWallpaper=false;
const signinPanel=document.getElementById('signin-panel'),lockScreen=document.getElementById('lock-screen'),puzzlePanel=document.getElementById('os-puzzle'),puzzleBox=puzzlePanel.querySelector('.os-puzzle'),puzzleToggle=document.getElementById('puzzle-toggle'),startMenu=document.getElementById('start-menu');
function refreshOsClock(){const now=new Date(),clock=localClock(now);document.getElementById('os-clock').textContent=clock.time;document.getElementById('os-date').textContent=clock.date;const timeEl=document.getElementById('desktop-clock-time'),dateEl=document.getElementById('desktop-clock-date'),tray=document.getElementById('desktop-time');if(timeEl)timeEl.textContent=now.toLocaleTimeString([],{hour:'numeric',minute:'2-digit',hour12:true});if(dateEl)dateEl.textContent=now.toLocaleDateString([],{month:'numeric',day:'numeric',year:'numeric'});if(tray)tray.dateTime=now.toISOString();}
function resetSignin(){clearTimeout(osUnlockTimer);osUnlocking=false;signinRevealed=false;lockScreen.classList.remove('signin-revealed');signinPanel.classList.remove('is-correct','is-wrong','is-unlocking');signinPanel.inert=true;document.getElementById('lock-curtain').inert=false;clearTimeout(puzzleCloseTimer);puzzlePanel.hidden=true;puzzlePanel.inert=false;puzzlePanel.classList.remove('is-open');puzzleBox.classList.remove('is-wrong','is-correct');lockScreen.classList.remove('puzzle-open');puzzleToggle.setAttribute('aria-expanded','false');document.getElementById('password-answer').value='';document.getElementById('answer-message').textContent='';document.getElementById('guest-signin').disabled=false;}
function revealSignin(){if(signinRevealed||laptopUnlocked)return;signinRevealed=true;lockScreen.classList.add('signin-revealed');signinPanel.inert=false;document.getElementById('lock-curtain').inert=true;document.getElementById('guest-signin').focus();}
function openLaptop(opener=document.activeElement){laptopReturnFocus=opener;laptopPowered=true;if(!laptopUnlocked)resetSignin();refreshOsClock();clearInterval(osClockTimer);osClockTimer=setInterval(refreshOsClock,LIUOS_CONFIG.clock.refreshMs);syncLaptop();laptopDialog.prepend(document.querySelector('.room-nav'));laptopDialog.showModal();document.dispatchEvent(new CustomEvent('laptop:opened'));announceApps();updateWallpaperState();(laptopUnlocked?document.getElementById('start-button'):document.getElementById('reveal-signin')).focus();}
function unlock(celebrate=false){if(osUnlocking)return;osUnlocking=true;document.getElementById('guest-signin').disabled=true;signinPanel.inert=true;const complete=()=>{if(!laptopDialog.open)return;laptopUnlocked=true;osUnlocking=false;syncLaptop();const desktop=document.getElementById('desktop');desktop.classList.remove('os-entering');void desktop.offsetWidth;desktop.classList.add('os-entering');document.getElementById('start-button').focus();};
 if(reducedMotion()){complete();return;}const fadeOut=()=>{signinPanel.classList.add('is-unlocking');osUnlockTimer=setTimeout(complete,LIUOS_CONFIG.transitionMs);};
 // Password: "Welcome!" shows in the popup, then the popup closes and the sign-in card fades up.
 if(celebrate){puzzlePanel.inert=true;puzzleBox.classList.add('is-correct');document.getElementById('answer-message').textContent='Welcome!';osUnlockTimer=setTimeout(()=>{closePuzzle();fadeOut();},LIUOS_CONFIG.puzzle.successMs);return;}
 // Guest: avatar pulse + ring, then the card fades up.
 signinPanel.classList.add('is-correct');osUnlockTimer=setTimeout(fadeOut,LIUOS_CONFIG.puzzle.celebrationMs);}
// The password popup. Closing it (✕ or Esc) returns to the sign-in card.
function openPuzzle(){clearTimeout(puzzleCloseTimer);puzzlePanel.hidden=false;puzzlePanel.inert=false;lockScreen.scrollTop=0;lockScreen.classList.add('puzzle-open');signinPanel.inert=true;puzzleToggle.setAttribute('aria-expanded','true');void puzzlePanel.offsetWidth;puzzlePanel.classList.add('is-open');document.getElementById('password-answer').focus();}
function closePuzzle(instant=false){if(puzzlePanel.hidden)return;puzzlePanel.classList.remove('is-open');puzzleToggle.setAttribute('aria-expanded','false');const done=()=>{puzzlePanel.hidden=true;lockScreen.classList.remove('puzzle-open');puzzleBox.classList.remove('is-wrong','is-correct');document.getElementById('password-answer').value='';document.getElementById('answer-message').textContent='';};clearTimeout(puzzleCloseTimer);if(instant||reducedMotion())done();else puzzleCloseTimer=setTimeout(done,200);if(!osUnlocking){signinPanel.inert=false;puzzleToggle.focus();}}
document.getElementById('reveal-signin').addEventListener('click',revealSignin);
laptopDialog.addEventListener('keydown',event=>{if(!event.target.closest('.room-nav')&&!laptopUnlocked&&!signinRevealed&&!['Escape','Shift','Control','Alt','Meta'].includes(event.key)){event.preventDefault();revealSignin();}});
document.getElementById('guest-signin').addEventListener('click',()=>unlock());
puzzleToggle.addEventListener('click',openPuzzle);
document.getElementById('puzzle-close').addEventListener('click',()=>closePuzzle());
document.getElementById('unlock-form').addEventListener('submit',e=>{e.preventDefault();if(osUnlocking)return;const answer=document.getElementById('password-answer').value.trim().toLowerCase(),correct=LIUOS_CONFIG.puzzle.answers.some(value=>value.trim().toLowerCase()===answer);document.getElementById('answer-message').textContent=correct?'Welcome!':'Not quite. Try a hint, or enter as guest.';if(correct)unlock(true);else{puzzleBox.classList.remove('is-wrong');void puzzleBox.offsetWidth;puzzleBox.classList.add('is-wrong');document.getElementById('password-answer').focus();}});
document.getElementById('riddle-hint').addEventListener('click',()=>document.getElementById('answer-message').textContent=LIUOS_CONFIG.puzzle.hint);
document.getElementById('skip-puzzle').addEventListener('click',()=>{closePuzzle(true);unlock();});
document.getElementById('power-off').addEventListener('click',()=>{hideOsMenus();for(const win of osWindows.values()){win.focusContent?.onClose?.();win.element.remove();}osWindows.clear();updateDock();laptopPowered=false;laptopUnlocked=false;resetSignin();startMenu.hidden=true;document.getElementById('start-button').setAttribute('aria-expanded','false');syncLaptop();laptopDialog.close();});
document.getElementById('start-button').addEventListener('click',()=>{const shouldOpen=startMenu.hidden;hideOsMenus();startMenu.hidden=!shouldOpen;document.getElementById('start-button').setAttribute('aria-expanded',String(!startMenu.hidden));if(!startMenu.hidden){placePopover(startMenu,document.getElementById('start-button'));document.getElementById('lock-laptop').focus();}});
document.getElementById('lock-laptop').addEventListener('click',()=>{hideOsMenus();laptopUnlocked=false;startMenu.hidden=true;document.getElementById('start-button').setAttribute('aria-expanded','false');resetSignin();syncLaptop();document.getElementById('reveal-signin').focus();});
document.getElementById('wallpaper-toggle').addEventListener('click',()=>{alternateWallpaper=!alternateWallpaper;updateWallpaperState();});
refreshOsClock();

document.getElementById('close-laptop').addEventListener('click',()=>laptopDialog.close());
laptopDialog.addEventListener('close',()=>{document.body.prepend(document.querySelector('.room-nav'));clearInterval(osClockTimer);clearTimeout(osUnlockTimer);if(osUnlocking){resetSignin();syncLaptop();}if(laptopReturnFocus instanceof HTMLElement)laptopReturnFocus.focus();updateWallpaperState();announceApps();document.dispatchEvent(new CustomEvent('laptop:closed'));});
document.addEventListener('laptop:open',event=>openLaptop(event.detail?.opener));
document.addEventListener('laptop:close',()=>{if(laptopDialog.open)laptopDialog.close();});
document.addEventListener('laptop:open-app',({detail:{name,opener}})=>{laptopPowered=true;laptopUnlocked=true;resetSignin();syncLaptop();if(!laptopDialog.open)openLaptop(opener);showApp(name);});
