function osIcon(name){return '<svg class="os-icon" viewBox="0 0 24 24" aria-hidden="true">'+iconPaths[name]+'</svg>';}
document.getElementById('start-button').innerHTML=osIcon('system');document.getElementById('os-search-button').innerHTML=osIcon('search');
function weatherFromCode(code,hour){if(code===0)return {icon:hour>=6&&hour<20?'sun':'moon',label:'Clear'};if(code<=3)return {icon:'cloud',label:'Cloudy'};if(code<=48)return {icon:'cloud',label:'Fog'};if(code<=67||code>=80&&code<=82)return {icon:'rain',label:'Rain'};if(code<=77||code>=85&&code<=86)return {icon:'snow',label:'Snow'};if(code>=95)return {icon:'rain',label:'Storm'};return {icon:'cloud',label:'Cloudy'};}
function renderWeather(icon,temp,label){const el=document.getElementById('os-weather'),cfg=LIUOS_CONFIG.weather;if(!el)return;el.innerHTML=osIcon(icon)+'<span class="os-weather-temp">'+(temp==null?'—':temp+'°')+'</span><span class="os-weather-label">'+label+'</span>';el.setAttribute('aria-label',temp==null?'Weather unavailable':temp+'° '+label+' in '+cfg.city);}
async function refreshWeather(){const cfg=LIUOS_CONFIG.weather;try{const data=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+cfg.latitude+'&longitude='+cfg.longitude+'&current=temperature_2m,weather_code&temperature_unit='+cfg.unit).then(r=>{if(!r.ok)throw new Error();return r.json();});const info=weatherFromCode(data.current.weather_code,new Date().getHours());renderWeather(info.icon,Math.round(data.current.temperature_2m),info.label);}catch{renderWeather('cloud',null,cfg.city);}}
function renderBattery(level,charging){const el=document.getElementById('os-battery');if(!el)return;const pct=Math.round(level*100);el.innerHTML=osIcon(charging?'plug':'battery')+'<span>'+pct+'%</span>';el.setAttribute('aria-label',charging?'Charging, '+pct+'%':'Battery '+pct+'%');el.title=el.getAttribute('aria-label');}
function initBattery(){if(!navigator.getBattery){renderBattery(1,true);return;}navigator.getBattery().then(battery=>{const update=()=>renderBattery(battery.level,battery.charging);update();battery.addEventListener('levelchange',update);battery.addEventListener('chargingchange',update);}).catch(()=>renderBattery(1,true));}
renderWeather('cloud',null,LIUOS_CONFIG.weather.city);refreshWeather();setInterval(refreshWeather,LIUOS_CONFIG.weather.refreshMs);initBattery();

// One renderer and one quad are shared by the lock screen and desktop.
// Do not create that WebGL context until LiuOS is actually open. Safari on iPhone
// was crashing when the room and this wallpaper both started on the first load.
let wallpaperController=null,wallpaperPromise=null;
async function ensureWallpaper(){
  if(wallpaperController)return wallpaperController;
  if(wallpaperPromise)return wallpaperPromise;
  wallpaperPromise=(async()=>{
    try{
      const wallpaperModule=await import(LIUOS_CONFIG.wallpaper.module);
      wallpaperController=wallpaperModule.createWallpaper(THREE,LIUOS_CONFIG.wallpaper,motionPreference,LIUOS_CONFIG.colors);
      return wallpaperController;
    }catch(error){
      console.warn('LiuOS wallpaper unavailable; showing the static background.',error);
      wallpaperPromise=null;
      return null;
    }
  })();
  return wallpaperPromise;
}
function updateWallpaperState(){
  if(!laptopDialog.open){
    if(safari&&wallpaperController){wallpaperController.dispose();wallpaperController=null;wallpaperPromise=null;}
    else wallpaperController?.setState({visible:false,covered:true,alternate:alternateWallpaper});
    return;
  }
  ensureWallpaper().then(controller=>{
    if(!controller||!laptopDialog.open)return;
    const desktop=document.getElementById('desktop');
    const unlocked=!desktop.hidden;
    const covered=unlocked&&Array.from(document.querySelectorAll('.os-window')).some(el=>!el.hidden&&!el.classList.contains('os-closing')&&(el.classList.contains('os-maximized')||desktop.clientWidth<=LIUOS_CONFIG.windows.mobileBreakpoint));
    controller.mount(unlocked?desktop:document.getElementById('lock-screen'));
    controller.setState({visible:true,covered,alternate:alternateWallpaper});
  });
}
window.addEventListener('pagehide',event=>{if(!event.persisted){wallpaperController?.dispose();wallpaperController=null;wallpaperPromise=null;}});
const osWindows=new Map();let nextWindowZ=10,selectedDesktopIcon=null;
// App builders use DOM text nodes for user-editable content.
// Desktop "Currently" card: my newest role (first in the experience list) and my school, from content/portfolio.js.
{const now=LIUOS_CONFIG.experience[0];document.getElementById('widget-role').textContent=now.role;document.getElementById('widget-org').textContent=now.organization;document.getElementById('widget-education').textContent=LIUOS_CONFIG.profile.education;}
function osNode(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el;}
function osTodo(parent,text){parent.append(osNode('span',text,'os-todo'));}
function osLink(label,url,download){const a=osNode('a',label,'os-app-link');a.href=url;if(download)a.download=download;else{a.target='_blank';a.rel='noopener noreferrer';}return a;}
function safeWebUrl(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null;}catch{return null;}}
