desktopElement.addEventListener('pointerdown',event=>{if(!event.target.closest('.start-menu,.os-search,#start-button,#os-search-button'))hideOsMenus();if(!event.target.closest('.os-window,.os-dock,.start-menu,.os-search,button,a,input'))clearWindowFocus();});
// Clicking empty desktop space (not a window, the dock, or a button) deselects the focused app, like a real desktop.
function clearWindowFocus(){let changed=false;for(const win of osWindows.values())if(win.element.classList.contains('os-focused')){win.element.classList.remove('os-focused');changed=true;}if(changed)updateDock();}
function handleLaptopEscape(){if(!puzzlePanel.hidden&&puzzlePanel.classList.contains('is-open')&&!osUnlocking){closePuzzle();return;}hideOsMenus();const focused=[...osWindows.values()].filter(w=>!w.minimized&&!w.closing).sort((a,b)=>Number(b.element.style.zIndex)-Number(a.element.style.zIndex))[0];if(laptopUnlocked&&focused)closeWindow(focused);else if(![...osWindows.values()].some(w=>w.closing))laptopDialog.close();}
laptopDialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(!event.repeat)handleLaptopEscape();}});
laptopDialog.addEventListener('cancel',event=>{event.preventDefault();handleLaptopEscape();});
window.addEventListener('resize',()=>{for(const win of osWindows.values()){if(win.wasMobile&&desktopElement.clientWidth>=LIUOS_CONFIG.windows.mobileBreakpoint)placeWindow(win);else clampWindow(win);win.wasMobile=desktopElement.clientWidth<LIUOS_CONFIG.windows.mobileBreakpoint;}if(!startMenu.hidden)placePopover(startMenu,document.getElementById('start-button'));if(!searchPanel.hidden)placePopover(searchPanel,document.getElementById('os-search-button'));updateWallpaperState();});

// Send the first screen picture. If the room isn't listening yet, it asks later with laptop:screen-request.
announceScreen(drawScreen());scheduleScreenClock();
